<?php namespace App\Models; use Illuminate\Database\Eloquent\Model; class Order extends Model { protected $fillable=['order_number','user_id','address_id','restaurant_table_id','discount_id','customer_name','phone','delivery_address','order_type','status','subtotal','discount_amount','delivery_fee','total','special_instructions','stock_deducted_at']; protected $casts=['subtotal'=>'decimal:2','discount_amount'=>'decimal:2','delivery_fee'=>'decimal:2','total'=>'decimal:2','stock_deducted_at'=>'datetime']; public function items(){return $this->hasMany(OrderItem::class);} public function payment(){return $this->hasOne(Payment::class);} public function user(){return $this->belongsTo(User::class);} }
